1	"use client";
2	
3	import { useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { addExcludedIp, removeExcludedIp } from "@/lib/actions-analytics";
6	
7	/** Manage the analytics IP exclude-list — "hide my own traffic". Excluded IPs are
8	 *  dropped from every visitor stat so the dashboard shows real public traffic. */
9	export function ExcludeIpPanel({ myIp, excluded }: { myIp: string; excluded: string[] }) {
10	  const router = useRouter();
11	  const [ip, setIp] = useState("");
12	  const [err, setErr] = useState("");
13	  const [busy, setBusy] = useState(false);
14	
15	  async function add(value: string) {
16	    setErr(""); setBusy(true);
17	    const res = await addExcludedIp(value);
18	    setBusy(false);
19	    if (res.error) { setErr(res.error); return; }
20	    setIp("");
21	    router.refresh();
22	  }
23	
24	  const myHidden = excluded.includes(myIp);
25	
26	  return (
27	    <div className="card space-y-3">
28	      <div className="flex items-center justify-between">
29	        <p className="text-sm font-semibold text-white">Hidden IPs</p>
30	        <span className="text-xs text-slate-500">excluded from all stats below</span>
31	      </div>
32	      <p className="text-xs text-slate-400">
33	        Your IP: <span className="font-mono text-slate-200">{myIp}</span>{" "}
34	        {myHidden ? (
35	          <span className="text-emerald-400">— hidden</span>
36	        ) : (
37	          <button className="text-brand-300 hover:underline disabled:opacity-50" disabled={busy} onClick={() => add(myIp)}>Hide my IP</button>
38	        )}
39	      </p>
40	      <div className="flex flex-wrap gap-2">
41	        {excluded.length === 0 && <span className="text-xs text-slate-500">None — all traffic is counted.</span>}
42	        {excluded.map((x) => (
43	          <span key={x} className="inline-flex items-center gap-1.5 rounded-full border border-white/10 bg-white/[0.03] px-2.5 py-1 text-xs font-mono text-slate-200">
44	            {x}
45	            <button aria-label={`Unhide ${x}`} className="text-slate-500 hover:text-red-400" onClick={async () => { await removeExcludedIp(x); router.refresh(); }}>✕</button>
46	          </span>
47	        ))}
48	      </div>
49	      <div className="flex gap-2">
50	        <input className="input text-sm font-mono" placeholder="Add IP to hide (e.g. 203.0.113.5)" value={ip} onChange={(e) => setIp(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && ip.trim()) add(ip); }} />
51	        <button className="btn-secondary text-sm" disabled={busy || !ip.trim()} onClick={() => add(ip)}>Add</button>
52	      </div>
53	      {err && <p className="text-sm text-red-400">{err}</p>}
54	    </div>
55	  );
56	}
