1	import Link from "next/link";
2	import { Badge, timeAgo } from "@/components/ui/primitives";
3	import type { Counted, RecentVisit } from "@/lib/analytics";
4	import { referrerHost } from "@/lib/analytics";
5	
6	/** Human "2m 34s" / "48s" / "—" from a dwell duration in ms. */
7	function fmtDwell(ms: number | null): string {
8	  if (ms == null || ms <= 0) return "—";
9	  const s = Math.round(ms / 1000);
10	  if (s < 60) return `${s}s`;
11	  const m = Math.floor(s / 60);
12	  const rem = s % 60;
13	  return rem ? `${m}m ${rem}s` : `${m}m`;
14	}
15	
16	/** Account cell: links a visit to its owning client's profile, or "—" if anon. */
17	function AccountCell({ account }: { account: RecentVisit["account"] }) {
18	  if (!account) return <span className="text-slate-600">—</span>;
19	  const paying = account.mrrCents > 0;
20	  return (
21	    <Link
22	      href={`/admin/users/${account.id}`}
23	      className={paying ? "text-emerald-300 hover:text-emerald-200" : "text-brand-300 hover:text-brand-200"}
24	      title={paying ? `Paying customer — ${account.email}` : account.email}
25	    >
26	      {account.name || account.email}
27	    </Link>
28	  );
29	}
30	
31	/** A compact ranked list ("top referrers", "top countries", …) with count bars. */
32	export function RankedList({
33	  title,
34	  sub,
35	  items,
36	  emptyLabel,
37	}: {
38	  title: string;
39	  sub?: string;
40	  items: Counted[];
41	  emptyLabel: string;
42	}) {
43	  const max = items.reduce((m, i) => Math.max(m, i.count), 0) || 1;
44	  return (
45	    <div className="card">
46	      <h2 className="font-semibold">{title}</h2>
47	      {sub && <p className="mt-1 text-xs text-slate-500">{sub}</p>}
48	      {items.length === 0 ? (
49	        <p className="py-6 text-sm text-slate-500">{emptyLabel}</p>
50	      ) : (
51	        <ul className="mt-3 space-y-2.5">
52	          {items.map((it) => (
53	            <li key={it.label}>
54	              <div className="flex items-center justify-between text-sm">
55	                <span className="truncate pr-3 text-slate-200">{it.label}</span>
56	                <span className="tabular-nums text-slate-400">{it.count}</span>
57	              </div>
58	              <div className="mt-1 h-1.5 overflow-hidden rounded-full bg-white/[0.05]">
59	                <div
60	                  className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500"
61	                  style={{ width: `${Math.max(6, (it.count / max) * 100)}%` }}
62	                />
63	              </div>
64	            </li>
65	          ))}
66	        </ul>
67	      )}
68	    </div>
69	  );
70	}
71	
72	function geoLabel(v: RecentVisit): string {
73	  const parts = [v.city, v.region, v.country].filter(Boolean);
74	  return parts.length ? parts.join(", ") : "—";
75	}
76	
77	/** Absolute timestamp for the date-range feed (where "3h ago" is unhelpful). */
78	function fmtStamp(d: Date): string {
79	  return new Date(d).toLocaleString(undefined, {
80	    year: "numeric",
81	    month: "short",
82	    day: "2-digit",
83	    hour: "2-digit",
84	    minute: "2-digit",
85	  });
86	}
87	
88	/**
89	 * Date-range traffic feed table. Same columns as the live table but with an
90	 * ABSOLUTE timestamp (the point of the date filter is to see exact dates), and
91	 * driven by the admin's chosen from/to range + sort direction.
92	 */
93	export function TrafficFeedTable({
94	  visits,
95	  total,
96	  shown,
97	}: {
98	  visits: RecentVisit[];
99	  total: number;
100	  shown: number;
101	}) {
102	  return (
103	    <div className="card p-0">
104	      <div className="flex flex-wrap items-baseline justify-between gap-2 px-5 pt-5">
105	        <div>
106	          <h2 className="font-semibold">Traffic feed</h2>
107	          <p className="mt-1 text-xs text-slate-500">
108	            Page views in the selected date range, sorted by date. Hidden IPs are excluded.
109	          </p>
110	        </div>
111	        <span className="text-xs text-slate-500">
112	          {total === 0
113	            ? "no matches"
114	            : shown < total
115	              ? `showing ${shown} of ${total.toLocaleString()}`
116	              : `${total.toLocaleString()} match${total === 1 ? "" : "es"}`}
117	        </span>
118	      </div>
119	      {visits.length === 0 ? (
120	        <p className="px-5 py-8 text-sm text-slate-500">
121	          No visits in this range. Widen the dates or clear the filter.
122	        </p>
123	      ) : (
124	        <div className="overflow-x-auto pt-3">
125	          <table className="table-shell">
126	            <thead>
127	              <tr>
128	                <th>Date</th>
129	                <th>IP</th>
130	                <th>Location</th>
131	                <th>Path</th>
132	                <th>Time on page</th>
133	                <th>Account</th>
134	                <th>Referrer</th>
135	                <th>Source</th>
136	              </tr>
137	            </thead>
138	            <tbody>
139	              {visits.map((v) => {
140	                const ref = referrerHost(v.referrer);
141	                return (
142	                  <tr key={v.id}>
143	                    <td className="whitespace-nowrap text-slate-400">{fmtStamp(v.createdAt)}</td>
144	                    <td className="whitespace-nowrap font-mono text-xs text-slate-400">{v.ip}</td>
145	                    <td className="whitespace-nowrap text-slate-300">{geoLabel(v)}</td>
146	                    <td className="max-w-[220px] truncate font-mono text-xs text-slate-200" title={v.path}>
147	                      {v.path}
148	                    </td>
149	                    <td className="whitespace-nowrap tabular-nums text-slate-400">{fmtDwell(v.durationMs)}</td>
150	                    <td className="max-w-[160px] truncate text-xs"><AccountCell account={v.account} /></td>
151	                    <td className="max-w-[160px] truncate text-slate-400" title={v.referrer ?? ""}>
152	                      {ref ?? <span className="text-slate-600">direct</span>}
153	                    </td>
154	                    <td>
155	                      <Badge tone={v.kind === "portal" ? "brand" : "slate"}>{v.kind}</Badge>
156	                    </td>
157	                  </tr>
158	                );
159	              })}
160	            </tbody>
161	          </table>
162	        </div>
163	      )}
164	    </div>
165	  );
166	}
