1	"use client";
2	
3	import { useState } from "react";
4	import { useRouter, useSearchParams } from "next/navigation";
5	import type { FeedDir, FeedKind } from "@/lib/analytics";
6	
7	/**
8	 * Date-range + source + sort controls for the visitor "Traffic feed". State
9	 * lives entirely in the URL query string (from/to/kind/dir), so the server
10	 * component re-queries on navigation and the filter is shareable/bookmarkable.
11	 * A plain form: no data fetching here, just router.push of the chosen params.
12	 */
13	export function TrafficFeedFilter({
14	  from,
15	  to,
16	  kind,
17	  dir,
18	}: {
19	  from: string;
20	  to: string;
21	  kind: FeedKind;
22	  dir: FeedDir;
23	}) {
24	  const router = useRouter();
25	  const sp = useSearchParams();
26	  const [f, setF] = useState(from);
27	  const [t, setT] = useState(to);
28	  const [k, setK] = useState<FeedKind>(kind);
29	  const [d, setD] = useState<FeedDir>(dir);
30	
31	  function apply() {
32	    const params = new URLSearchParams(sp.toString());
33	    const set = (key: string, val: string) => (val ? params.set(key, val) : params.delete(key));
34	    set("from", f);
35	    set("to", t);
36	    set("kind", k === "all" ? "" : k);
37	    set("dir", d === "desc" ? "" : d);
38	    // A new filter invalidates whatever page the admin was on (it may no
39	    // longer exist against the new result set), so always land back on 1.
40	    params.delete("page");
41	    const qs = params.toString();
42	    router.push(qs ? `/admin/visitors?${qs}` : "/admin/visitors");
43	  }
44	
45	  function clear() {
46	    setF(""); setT(""); setK("all"); setD("desc");
47	    router.push("/admin/visitors");
48	  }
49	
50	  const dirty = f !== from || t !== to || k !== kind || d !== dir;
51	  const anyFilter = from || to || kind !== "all" || dir !== "desc";
52	
53	  return (
54	    <div className="card space-y-3">
55	      <div className="flex items-center justify-between">
56	        <p className="text-sm font-semibold text-white">Filter by date</p>
57	        <span className="text-xs text-slate-500">sort the traffic feed by an explicit range</span>
58	      </div>
59	      <div className="flex flex-wrap items-end gap-3">
60	        <label className="flex flex-col gap-1 text-xs text-slate-400">
61	          From
62	          <input
63	            type="date"
64	            className="input text-sm"
65	            value={f}
66	            max={t || undefined}
67	            onChange={(e) => setF(e.target.value)}
68	          />
69	        </label>
70	        <label className="flex flex-col gap-1 text-xs text-slate-400">
71	          To
72	          <input
73	            type="date"
74	            className="input text-sm"
75	            value={t}
76	            min={f || undefined}
77	            onChange={(e) => setT(e.target.value)}
78	          />
79	        </label>
80	        <label className="flex flex-col gap-1 text-xs text-slate-400">
81	          Source
82	          <select className="input text-sm" value={k} onChange={(e) => setK(e.target.value as FeedKind)}>
83	            <option value="all">All traffic</option>
84	            <option value="marketing">Marketing site</option>
85	            <option value="portal">Portal</option>
86	          </select>
87	        </label>
88	        <label className="flex flex-col gap-1 text-xs text-slate-400">
89	          Sort
90	          <select className="input text-sm" value={d} onChange={(e) => setD(e.target.value as FeedDir)}>
91	            <option value="desc">Newest first</option>
92	            <option value="asc">Oldest first</option>
93	          </select>
94	        </label>
95	        <button className="btn-secondary text-sm" disabled={!dirty} onClick={apply}>
96	          Apply
97	        </button>
98	        {anyFilter && (
99	          <button className="text-sm text-slate-400 hover:text-red-400" onClick={clear}>
100	            Clear
101	          </button>
102	        )}
103	      </div>
104	    </div>
105	  );
106	}
