1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	import { geoOrthographic, geoPath, geoGraticule10, geoDistance } from "d3-geo";
5	import type { GeoPermissibleObjects } from "d3-geo";
6	import { feature } from "topojson-client";
7	import type { Topology, GeometryCollection } from "topojson-specification";
8	import type { FeatureCollection, Geometry } from "geojson";
9	
10	/**
11	 * Live activity globe. A real orthographic-projection Earth rendered with
12	 * Canvas 2D: Natural Earth country landmasses + outlines (public-domain
13	 * `world-atlas` topojson, shipped as /countries-110m.json), a subtle graticule,
14	 * an ocean-tinted sphere with a soft outer glow, and slow auto-rotation.
15	 *
16	 * Recent visitor lat/lng are drawn as pulsing markers (a core dot with an
17	 * expanding/fading ring), colored by source per the legend (marketing = green,
18	 * portal = violet). Occlusion is handled by the orthographic hemisphere: land
19	 * is clipped by d3's geoOrthographic (clipAngle 90), and each marker's angular
20	 * distance to the projection centre decides whether it is hidden (back) or how
21	 * dim it is (near the limb).
22	 *
23	 * Honors `prefers-reduced-motion` by holding a near-static frame.
24	 */
25	
26	export type GlobePoint = {
27	  lat: number;
28	  lng: number;
29	  city: string | null;
30	  country: string | null;
31	  kind: string;
32	};
33	
34	type World = { land: FeatureCollection<Geometry>; borders: FeatureCollection<Geometry> };
35	
36	// World geometry: fetched once and cached across mounts.
37	let worldCache: World | null = null;
38	let worldPromise: Promise<World | null> | null = null;
39	
40	async function loadWorld(): Promise<World | null> {
41	  if (worldCache) return worldCache;
42	  if (!worldPromise) {
43	    worldPromise = fetch("/countries-110m.json")
44	      .then((r) => r.json())
45	      .then((topo: Topology) => {
46	        const land = feature(
47	          topo,
48	          topo.objects.land as GeometryCollection,
49	        ) as FeatureCollection<Geometry>;
50	        const borders = feature(
51	          topo,
52	          topo.objects.countries as GeometryCollection,
53	        ) as FeatureCollection<Geometry>;
54	        worldCache = { land, borders };
55	        return worldCache;
56	      })
57	      .catch(() => null);
58	  }
59	  return worldPromise;
60	}
61	
62	export default function VisitorGlobe({ points }: { points: GlobePoint[] }) {
63	  const canvasRef = useRef<HTMLCanvasElement>(null);
64	
65	  useEffect(() => {
66	    const canvas = canvasRef.current;
67	    if (!canvas) return;
68	    const ctx = canvas.getContext("2d");
69	    if (!ctx) return;
70	
71	    const reduced =
72	      typeof window !== "undefined" &&
73	      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
74	
75	    let raf = 0;
76	    let disposed = false;
77	    let world: World | null = worldCache;
78	
79	    // Logical drawing size; backing store scaled for crisp HiDPI.
80	    const SIZE = 460;
81	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
82	    canvas.width = SIZE * dpr;
83	    canvas.height = SIZE * dpr;
84	    ctx.scale(dpr, dpr);
85	
86	    const cx = SIZE / 2;
87	    const cy = SIZE / 2;
88	    const R = SIZE / 2 - 24;
89	    const TILT = -16; // centre the view a touch north of the equator
90	
91	    // Orthographic projection fitted to the sphere disc. clipAngle 90 (the d3
92	    // default) hides back-hemisphere land automatically.
93	    const projection = geoOrthographic().scale(R).translate([cx, cy]).clipAngle(90);
94	    const path = geoPath(projection, ctx);
95	    const graticule = geoGraticule10() as unknown as GeoPermissibleObjects;
96	
97	    // Each visit as a [lng, lat] pair (d3 order) with a random pulse phase.
98	    const markers = points.map((p) => ({
99	      coord: [p.lng, p.lat] as [number, number],
100	      seed: Math.random() * Math.PI * 2,
101	      portal: p.kind === "portal",
102	    }));
103	
104	    let last = 0;
105	    let lambda = 0; // spin angle around the polar axis
106	    let acc = 0;
107	    const FRAME_MS = 1000 / 30; // throttle draws to ~30fps to keep CPU reasonable
108	
109	    function render(t: number) {
110	      ctx!.clearRect(0, 0, SIZE, SIZE);
111	
112	      // Soft outer glow behind the sphere.
113	      const glow = ctx!.createRadialGradient(cx, cy, R * 0.9, cx, cy, R * 1.28);
114	      glow.addColorStop(0, "rgba(138,112,251,0.18)");
115	      glow.addColorStop(1, "rgba(138,112,251,0)");
116	      ctx!.beginPath();
117	      ctx!.arc(cx, cy, R * 1.28, 0, Math.PI * 2);
118	      ctx!.fillStyle = glow;
119	      ctx!.fill();
120	
121	      // Ocean sphere with a radial shade for volume.
122	      const ocean = ctx!.createRadialGradient(cx - R * 0.35, cy - R * 0.4, R * 0.15, cx, cy, R);
123	      ocean.addColorStop(0, "rgba(59,130,246,0.20)");
124	      ocean.addColorStop(0.55, "rgba(40,30,90,0.42)");
125	      ocean.addColorStop(1, "rgba(10,8,25,0.72)");
126	      ctx!.beginPath();
127	      ctx!.arc(cx, cy, R, 0, Math.PI * 2);
128	      ctx!.fillStyle = ocean;
129	      ctx!.fill();
130	
131	      // Graticule on the visible hemisphere.
132	      ctx!.beginPath();
133	      path(graticule);
134	      ctx!.lineWidth = 0.6;
135	      ctx!.strokeStyle = "rgba(255,255,255,0.055)";
136	      ctx!.stroke();
137	
138	      if (world) {
139	        // Country landmasses — filled violet-slate.
140	        ctx!.beginPath();
141	        path(world.land as unknown as GeoPermissibleObjects);
142	        ctx!.fillStyle = "rgba(139,120,225,0.20)";
143	        ctx!.fill();
144	
145	        // Country outlines.
146	        ctx!.beginPath();
147	        path(world.borders as unknown as GeoPermissibleObjects);
148	        ctx!.lineWidth = 0.5;
149	        ctx!.strokeStyle = "rgba(170,150,255,0.30)";
150	        ctx!.stroke();
151	      }
152	
153	      // Rim light on the sphere edge.
154	      ctx!.beginPath();
155	      ctx!.arc(cx, cy, R, 0, Math.PI * 2);
156	      ctx!.lineWidth = 1.2;
157	      ctx!.strokeStyle = "rgba(138,112,251,0.5)";
158	      ctx!.stroke();
159	
160	      // Visit markers — only the front hemisphere, with a time-based pulse.
161	      const rot = projection.rotate();
162	      const centreLL: [number, number] = [-rot[0], -rot[1]];
163	      for (const m of markers) {
164	        const dist = geoDistance(m.coord, centreLL);
165	        if (dist >= Math.PI / 2) continue; // behind the globe
166	        const xy = projection(m.coord);
167	        if (!xy) continue;
168	        const depth = Math.cos(dist); // 1 at centre, 0 at the limb
169	        const edgeFade = 0.35 + 0.65 * depth;
170	        const core = m.portal ? "138,112,251" : "52,211,153"; // violet vs emerald
