import { db } from "./lib/db";
import { setSetting } from "./lib/settings";
import bcrypt from "bcryptjs";
import { SignJWT } from "jose";

async function main() {
  const passwordHash = await bcrypt.hash("Test1234!", 10);
  const admin = await db.user.upsert({
    where: { email: "wip-admin@example.test" },
    update: {},
    create: {
      email: "wip-admin@example.test",
      passwordHash,
      name: "WIP Admin",
      role: "ADMIN",
    },
  });

  // A pile of "hidden IPs" (~22, matching the reported clutter) so the
  // collapsed/modal behavior (fix #1) has something real to show.
  const hiddenIps = Array.from({ length: 22 }, (_, i) => `10.0.${Math.floor(i / 255)}.${i % 255}`);
  await setSetting("analytics_excluded_ips", hiddenIps.join(","));

  // Clear any previous run's visits for this seed's synthetic IP range.
  await db.visit.deleteMany({ where: { ip: { startsWith: "203.0.113." } } });

  const now = Date.now();
  const paths = ["/", "/pricing", "/blog/post-1", "/game-servers", "/vps", "/about", "/contact"];
  const kinds = ["marketing", "portal"];
  const rows = [];
  // 62 rows spread over distinct 1-minute-apart timestamps (never duplicate
  // createdAt) so offset pagination has zero tie-order ambiguity — isolates
  // whether the reported "broken" pagination is a UI/nav bug vs a data-order
  // bug. 62 rows / 25 per page = 3 pages (25/25/12).
  for (let i = 0; i < 62; i++) {
    rows.push({
      ip: `203.0.113.${i % 250}`,
      path: paths[i % paths.length],
      referrer: i % 3 === 0 ? "https://google.com/search" : null,
      kind: kinds[i % kinds.length],
      country: "US",
      region: "CA",
      city: "San Francisco",
      lat: 37.77,
      lng: -122.41,
      geocoded: true,
      createdAt: new Date(now - i * 60_000),
    });
  }
  await db.visit.createMany({ data: rows });

  const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
  const token = await new SignJWT({ sub: admin.id, sv: 0, typ: "session" })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("30d")
    .sign(secret);

  console.log("ADMIN_ID=" + admin.id);
  console.log("SESSION_TOKEN=" + token);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });

