"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { addExcludedIp, removeExcludedIp } from "@/lib/actions-analytics";

/** Manage the analytics IP exclude-list — "hide my own traffic". Excluded IPs are
 *  dropped from every visitor stat so the dashboard shows real public traffic.
 *
 *  The excluded-IP list can grow long (every admin/office/bot IP anyone has ever
 *  hidden), so it stays collapsed behind a "View hidden IPs" button instead of
 *  rendering every chip inline — a wall of IP chips at the top of the page was
 *  drowning out the actual analytics. The full list, remove buttons, and the
 *  add-IP form all still live in the popup this opens. */
export function ExcludeIpPanel({ myIp, excluded }: { myIp: string; excluded: string[] }) {
  const [open, setOpen] = useState(false);
  const myHidden = excluded.includes(myIp);

  return (
    <div className="card space-y-3">
      <div className="flex items-center justify-between">
        <p className="text-sm font-semibold text-white">Hidden IPs</p>
        <span className="text-xs text-slate-500">excluded from all stats above</span>
      </div>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-xs text-slate-400">
          Your IP: <span className="font-mono text-slate-200">{myIp}</span>{" "}
          {myHidden ? (
            <span className="text-emerald-400">— hidden</span>
          ) : (
            <span className="text-slate-500">— not hidden</span>
          )}
        </p>
        <button className="btn-secondary text-sm" onClick={() => setOpen(true)}>
          View hidden IPs ({excluded.length})
        </button>
      </div>
      {open && <HiddenIpsModal myIp={myIp} excluded={excluded} onClose={() => setOpen(false)} />}
    </div>
  );
}

/** Popup listing every excluded IP (with its unhide "✕") plus the add-IP form —
 *  matches the modal shell already used elsewhere in the admin (see BoardClient's
 *  AppSettingsModal/CardModal): dark backdrop, centered rounded panel, Escape
 *  and backdrop-click to close. */
function HiddenIpsModal({
  myIp,
  excluded,
  onClose,
}: {
  myIp: string;
  excluded: string[];
  onClose: () => void;
}) {
  const router = useRouter();
  const [ip, setIp] = useState("");
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") onClose();
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  async function add(value: string) {
    setErr("");
    setBusy(true);
    const res = await addExcludedIp(value);
    setBusy(false);
    if (res.error) {
      setErr(res.error);
      return;
    }
    setIp("");
    router.refresh();
  }

  const myHidden = excluded.includes(myIp);

  return (
    <div
      className="fixed inset-0 z-40 flex items-start justify-center overflow-y-auto bg-black/60 p-4 sm:p-8"
      onMouseDown={onClose}
    >
      <div
        className="my-4 w-full max-w-lg rounded-2xl border border-white/10 bg-navy-900 p-5 shadow-2xl"
        onMouseDown={(e) => e.stopPropagation()}
      >
        <div className="mb-4 flex items-center justify-between gap-3">
          <h2 className="text-lg font-semibold text-white">Hidden IPs ({excluded.length})</h2>
          <button onClick={onClose} className="rounded-lg px-2 py-1 text-slate-400 hover:bg-white/5" aria-label="Close">
            ✕
          </button>
        </div>

        <p className="mb-3 text-xs text-slate-400">
          Your IP: <span className="font-mono text-slate-200">{myIp}</span>{" "}
          {myHidden ? (
            <span className="text-emerald-400">— hidden</span>
          ) : (
            <button className="text-brand-300 hover:underline disabled:opacity-50" disabled={busy} onClick={() => add(myIp)}>
              Hide my IP
            </button>
          )}
        </p>

        <div className="flex max-h-64 flex-wrap gap-2 overflow-y-auto">
          {excluded.length === 0 && <span className="text-xs text-slate-500">None — all traffic is counted.</span>}
          {excluded.map((x) => (
            <span
              key={x}
              className="inline-flex items-center gap-1.5 rounded-full border border-white/10 bg-white/[0.03] px-2.5 py-1 text-xs font-mono text-slate-200"
            >
              {x}
              <button
                aria-label={`Unhide ${x}`}
                className="text-slate-500 hover:text-red-400"
                onClick={async () => {
                  await removeExcludedIp(x);
                  router.refresh();
                }}
              >
                ✕
              </button>
            </span>
          ))}
        </div>

        <div className="mt-4 flex gap-2">
          <input
            className="input text-sm font-mono"
            placeholder="Add IP to hide (e.g. 203.0.113.5)"
            value={ip}
            onChange={(e) => setIp(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && ip.trim()) add(ip);
            }}
          />
          <button className="btn-secondary text-sm" disabled={busy || !ip.trim()} onClick={() => add(ip)}>
            Add
          </button>
        </div>
        {err && <p className="mt-2 text-sm text-red-400">{err}</p>}
      </div>
    </div>
  );
}

