export async function visitFeed(f: FeedFilter): Promise<RecentVisit[]> {
  const take = Math.min(Math.max(f.take ?? 25, 1), 500);
  const dir = f.dir === "asc" ? "asc" : "desc";
  const rows = await db.visit.findMany({
    where: await feedWhere(f),
    // `id` is a tiebreaker, not just `createdAt`: several visits can share the
    // exact same millisecond timestamp (bursts of near-simultaneous pageviews
    // are common), and Postgres makes no ordering guarantee among rows that
    // tie on the sort key. Without a unique secondary key, `skip`/`take`
    // offset pagination can silently reshuffle those tied rows between two
    // queries — a row seen on page 1 reappearing on page 2, or a row between
    // them never appearing at all. `id` (a cuid, so already unique) closes
    // that gap and makes every page's window fully deterministic.
    orderBy: [{ createdAt: dir }, { id: dir }],
    skip: Math.max(f.skip ?? 0, 0),
    take,
    select: RECENT_VISIT_SELECT,
  });
  return withAccounts(rows);

