import { chromium } from "playwright";
import { readFileSync } from "fs";

const TOKEN = readFileSync("/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/token.txt", "utf8").trim();
const BASE = "http://127.0.0.1:4173";

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
await context.addCookies([
  { name: "nxeon_session", value: TOKEN, domain: "127.0.0.1", path: "/", httpOnly: true, sameSite: "Lax" },
]);
const page = await context.newPage();
await page.goto(`${BASE}/admin/visitors`, { waitUntil: "load" });
await page.locator('button:has-text("Got it")').click().catch(() => {});
const viewBtn = page.locator('button:has-text("View hidden IPs")');
await viewBtn.scrollIntoViewIfNeeded();
await viewBtn.click();
await page.waitForSelector('text=Hidden IPs (');

const info = await page.evaluate(() => {
  const modal = [...document.querySelectorAll("div")].find(d => d.className.includes("fixed inset-0"));
  if (!modal) return { found: false };
  const rect = modal.getBoundingClientRect();
  const cs = getComputedStyle(modal);
  // Walk ancestors looking for transform/filter/contain/perspective/will-change that create a containing block.
  const offenders = [];
  let el = modal.parentElement;
  while (el) {
    const s = getComputedStyle(el);
    if (s.transform !== "none" || s.filter !== "none" || s.perspective !== "none" ||
        (s.willChange && /transform|perspective|filter/.test(s.willChange)) ||
        (s.contain && s.contain !== "none") || s.backdropFilter !== "none") {
      offenders.push({ tag: el.tagName, cls: el.className, transform: s.transform, filter: s.filter, contain: s.contain, willChange: s.willChange, backdropFilter: s.backdropFilter });
    }
    el = el.parentElement;
  }
  return {
    found: true,
    position: cs.position,
    rect: { top: rect.top, bottom: rect.bottom, left: rect.left, right: rect.right },
    scrollY: window.scrollY,
    innerHeight: window.innerHeight,
    offenders,
  };
});
console.log(JSON.stringify(info, null, 2));
